import type { Meta, StoryObj } from "@storybook/nextjs";
import { Box, Flex, Text } from "../../atoms";
import { EthIcon } from "../../icons";
import { MetricWidget } from "../MetricWidget/MetricWidget";
import {
  MetricWidgetsGrid,
  MetricValueText,
  metricWidgetCellCss,
  type MetricGridColumns,
} from "./MetricWidgetsGrid";

const meta: Meta<typeof MetricWidgetsGrid> = {
  title: "Design System/Molecules/MetricWidgetsGrid",
  component: MetricWidgetsGrid,
  parameters: {
    layout: "padded",
    docs: {
      description: {
        component: `
Equal-width metric rows for Launchpad (Explorer, Positions, Operator dashboard, cluster details).

**Exports**
- \`MetricWidgetsGrid\` — responsive CSS grid (\`columns={2|3|4}\`)
- \`metricWidgetCellCss\` — pass as \`css\` on each \`MetricWidget\` in the grid
- \`MetricValueText\` — typography for simple numeric metrics (aligns with ETH rows)

**Breakpoints** (\`@sm\` ≤900px, \`@md\` ≤1200px)
- \`columns={4}\`: 4 → 2×2 → 1 (Explorer, cluster details)
- \`columns={3}\`: 3 → 1 (Positions)
- \`columns={2}\`: 2 → 1 (operator list when Active Stake is hidden)

**Usage**
\`\`\`tsx
<MetricWidgetsGrid columns={4}>
  <MetricWidget css={metricWidgetCellCss} heading="Operators" content={<MetricValueText>306</MetricValueText>} />
</MetricWidgetsGrid>
\`\`\`
        `,
      },
    },
  },
  argTypes: {
    columns: {
      control: "select",
      options: [2, 3, 4] satisfies MetricGridColumns[],
      description: "Number of equal columns before responsive collapse",
    },
  },
};

export default meta;

type Story = StoryObj<typeof MetricWidgetsGrid>;

const EthMetricContent = ({
  primaryValue,
  secondaryValue,
}: {
  primaryValue: string;
  secondaryValue: string;
}) => (
  <Flex
    css={{
      alignItems: "center",
      justifyContent: "space-between",
      width: "100%",
    }}
  >
    <Flex css={{ alignItems: "center", gap: "$2", whiteSpace: "nowrap" }}>
      <EthIcon size={20} />
      <Text
        variant="h4"
        css={{
          fontVariantNumeric: "tabular-nums",
          lineHeight: "32px",
          fontWeight: "$semibold",
        }}
      >
        {primaryValue}
      </Text>
    </Flex>
    <Text
      variant="h4"
      css={{
        color: "$muted",
        whiteSpace: "nowrap",
        fontVariantNumeric: "tabular-nums",
        lineHeight: "32px",
        fontWeight: "$regular",
      }}
    >
      {secondaryValue}
    </Text>
  </Flex>
);

type MetricRowProps = {
  columns: MetricGridColumns;
  isLoading?: boolean;
};

const ExplorerMetricsRow = ({ columns, isLoading }: MetricRowProps) => (
  <Box css={{ width: "100%", maxWidth: "1200px" }}>
    <MetricWidgetsGrid columns={columns}>
      <MetricWidget
        css={metricWidgetCellCss}
        heading="Total Value Staked (TVS)"
        content={
          <EthMetricContent primaryValue="388,121" secondaryValue="$781M" />
        }
        tooltipContent="The total amount of ETH and USD value currently staked on Obol DVs"
        isLoading={isLoading}
      />
      <MetricWidget
        css={metricWidgetCellCss}
        heading="Rewards"
        content={<EthMetricContent primaryValue="30" secondaryValue="$60,314" />}
        tooltipContent="Total staking rewards earned by Obol DVs"
        isLoading={isLoading}
      />
      <MetricWidget
        css={metricWidgetCellCss}
        heading="Operators"
        content={<MetricValueText>306</MetricValueText>}
        tooltipContent="Total number of distinct operators running an Obol DV"
        isLoading={isLoading}
      />
      <MetricWidget
        css={metricWidgetCellCss}
        heading="Total Active Clusters"
        content={<MetricValueText>79</MetricValueText>}
        tooltipContent="Total number of clusters having at least one active DV"
        isLoading={isLoading}
      />
    </MetricWidgetsGrid>
  </Box>
);

const PositionsMetricsRow = ({ isLoading }: { isLoading?: boolean }) => (
  <Box css={{ width: "100%", maxWidth: "1200px" }}>
    <MetricWidgetsGrid columns={3}>
      <MetricWidget
        css={metricWidgetCellCss}
        heading="Total Staked"
        content={<EthMetricContent primaryValue="128.5" secondaryValue="$412K" />}
        tooltipContent="Total ETH staked across your positions"
        isLoading={isLoading}
      />
      <MetricWidget
        css={metricWidgetCellCss}
        heading="Claimable"
        content={<EthMetricContent primaryValue="0.42" secondaryValue="$1,340" />}
        tooltipContent="Rewards available to claim"
        isLoading={isLoading}
      />
      <MetricWidget
        css={metricWidgetCellCss}
        heading="Positions"
        content={<MetricValueText>12</MetricValueText>}
        tooltipContent="Number of DV positions for this address"
        isLoading={isLoading}
      />
    </MetricWidgetsGrid>
  </Box>
);

const OperatorDashboardRow = ({
  showActiveStake,
  isLoading,
}: {
  showActiveStake?: boolean;
  isLoading?: boolean;
}) => (
  <Box css={{ width: "100%", maxWidth: "900px" }}>
    <MetricWidgetsGrid columns={showActiveStake ? 3 : 2}>
      {showActiveStake && (
        <MetricWidget
          css={metricWidgetCellCss}
          heading="Active Stake"
          content={<EthMetricContent primaryValue="64.0" secondaryValue="$205K" />}
          tooltipContent="ETH actively staked by this operator"
          isLoading={isLoading}
        />
      )}
      <MetricWidget
        css={metricWidgetCellCss}
        heading="Clusters"
        content={<MetricValueText>8</MetricValueText>}
        tooltipContent="Clusters this operator participates in"
        isLoading={isLoading}
      />
      <MetricWidget
        css={metricWidgetCellCss}
        heading="Validators"
        content={<MetricValueText>24</MetricValueText>}
        tooltipContent="Validators run by this operator"
        isLoading={isLoading}
      />
    </MetricWidgetsGrid>
  </Box>
);

