import type { JSX } from "react";
import { CSS } from "../../../stitches.config";
import { Box, Text, Flex } from "../../atoms";
import {
  ClusterAndValidatorStatus,
  MetricValidatorStatus,
} from "../MetricValidatorStatus/MetricValidatorStatus";
import { BoxCard } from "../Card/Card";
import { TooltipComponent } from "../../atoms/Tooltip/Tooltip";
import { HelpIcon } from "../../icons";
import { ReactNode, isValidElement } from "react";
import { Skeleton } from "../../atoms/Skeleton/Skeleton";

type BaseMetricWidgetProps = {
  heading: string | ReactNode;
  tooltipContent?: string | ReactNode;
  css?: CSS;
  isLoading?: boolean;
};

export type MetricWidgetProps =
  | (BaseMetricWidgetProps & {
      status: ClusterAndValidatorStatus;
      content?: never;
    })
  | (BaseMetricWidgetProps & { status?: never; content: ReactNode });

export const MetricWidget: React.FC<MetricWidgetProps> = ({
  css,
  heading,
  tooltipContent,
  content,
  status,
  isLoading,
}): JSX.Element => {
  // Render heading section - maintain backward compatibility for string headings
  const renderHeading = () => {
    if (isLoading) {
      return (
        <Box css={{ width: "50%" }}>
          <Skeleton variant="text" />
        </Box>
      );
    }

    // If heading is a React element, render it with space-between support
    if (isValidElement(heading)) {
      return (
        <Flex
          css={{
            width: "100%",
            justifyContent: "space-between",
            alignItems: "baseline",
          }}
        >
          {heading}
        </Flex>
      );
    }

    // If heading is not a React element, render with backward compatibility
    if (tooltipContent) {
      return (
        <Flex css={{ gap: "$xxxs", alignItems: "center" }}>
          <Text
            variant="subline"
            color="body"
            css={{ textTransform: "uppercase" }}
          >
            {heading}
          </Text>
          <TooltipComponent side="right" content={tooltipContent}>
            <Box css={{ display: "flex" }}>
              <HelpIcon size="md" />
            </Box>
          </TooltipComponent>
        </Flex>
      );
    }
    return (
      <Text variant="subline" color="body" css={{ textTransform: "uppercase" }}>
        {heading}
      </Text>
    );
  };

  // Render content section
  const renderContent = () => {
    if (isLoading) {
      return (
        <Box css={{ width: "50px" }}>
          <Skeleton variant="title" />
        </Box>
      );
    }

    if (status) {
      return <MetricValidatorStatus status={status} />;
    }

    // If content is a ReactNode, render it directly (handles both single and multiple elements)
    return (
      <Flex css={{ gap: "$xs", alignItems: "center" }}>
        {isValidElement(content) ? (
          content
        ) : (
          <Text variant="h4" css={{ textTransform: "capitalize" }}>
            {content}
          </Text>
        )}
      </Flex>
    );
  };

  return (
    <BoxCard className="box-card" css={css} metricWidget>
      {/* Heading section */}
      {renderHeading()}
      {/* Content section */}
      {renderContent()}
    </BoxCard>
  );
};
